types.text:
type CodeBlockArms = {
  mode?: 'code';
  source: string;
  before?: never;
  after?: never;
} | {
  mode: 'diff';
  before: string;
  after: string;
  source?: never;
};

type CodeBlockOwnProps = {
  mode?: 'code' | 'diff';
  source?: string;
  before?: string;
  after?: string;
  language?: string;
  filename?: string;
  lineNumbers?: boolean;
  copyable?: boolean;
  wrap?: boolean;
};
